<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">    models</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">: [</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">qwen2.5-7b</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">, </span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">gpt-4o-mini</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">]</span></span>
